#include "BlendPolicy.h"
#include <algorithm>
#include <cmath>
namespace drawborad { namespace {
std::uint16_t rd(const std::uint8_t*p,Depth d){return d==Depth::U8?std::uint16_t(p[0])*257u:std::uint16_t(p[0]|(std::uint16_t(p[1])<<8));}void wr(std::uint8_t*p,Depth d,std::uint16_t v){if(d==Depth::U8)p[0]=std::uint8_t((std::uint32_t(v)+128)/257);else{p[0]=std::uint8_t(v);p[1]=std::uint8_t(v>>8);}}
std::uint16_t bc(std::uint16_t s,std::uint16_t d,BlendMode m){switch(m){case BlendMode::Normal:return s;case BlendMode::Multiply:return std::uint16_t((std::uint64_t(s)*d+32767)/65535);case BlendMode::Screen:return std::uint16_t(65535-(std::uint64_t(65535-s)*(65535-d)+32767)/65535);case BlendMode::Darken:return std::min(s,d);case BlendMode::Lighten:return std::max(s,d);}return s;}
}
BlendSupport supportedBlend(PixelFormat f,BlendMode m){bool fmt=(f.mode==ColorMode::RGB||f.mode==ColorMode::CMYK)&&(f.depth==Depth::U8||f.depth==Depth::U16)&&f.alpha;bool mode=m==BlendMode::Normal||m==BlendMode::Multiply||m==BlendMode::Screen||m==BlendMode::Darken||m==BlendMode::Lighten;return{fmt&&mode,{}};}
Result<TileData> blendPixels(const BlendRequest&q){if(!supportedBlend(q.src.format,q.mode).enabled)return error(ErrorCode::UnsupportedFeature,"blend.unsupported");if(q.src.format!=q.dst.format||q.src.profileId!=q.dst.profileId||q.src.width!=q.dst.width||q.src.height!=q.dst.height||!std::isfinite(q.opacity)||q.opacity<0||q.opacity>1)return error(ErrorCode::InvalidInput,"blend.layout");unsigned c=q.src.format.mode==ColorMode::RGB?3u:4u,b=q.src.format.depth==Depth::U16?2u:1u;auto pb=(c+1)*b;TileData o=q.dst;for(std::uint32_t y=0;y<q.src.height;y++){auto*s=q.src.bytes.data()+std::size_t(y*q.src.rowStride);auto*d=q.dst.bytes.data()+std::size_t(y*q.dst.rowStride);auto*z=o.bytes.data()+std::size_t(y*o.rowStride);for(std::uint32_t x=0;x<q.src.width;x++){auto*sp=s+x*pb;auto*dp=d+x*pb;auto*op=z+x*pb;std::uint32_t sa=std::uint32_t(std::llround(rd(sp+c*b,q.src.format.depth)*q.opacity)),da=rd(dp+c*b,q.src.format.depth);std::uint64_t den=std::uint64_t(sa)*65535+std::uint64_t(da)*(65535-sa);auto oa=std::uint16_t((den+32767)/65535);for(unsigned k=0;k<c;k++){auto sc=bc(rd(sp+k*b,q.src.format.depth),rd(dp+k*b,q.src.format.depth),q.mode),dc=rd(dp+k*b,q.src.format.depth);std::uint16_t oc=den?std::uint16_t((std::uint64_t(sc)*sa*65535+std::uint64_t(dc)*da*(65535-sa)+den/2)/den):0;wr(op+k*b,q.src.format.depth,oc);}wr(op+c*b,q.src.format.depth,oa);}}return o;}
Result<TileData> softProof(const ProofRequest&q,const ColorService&s){auto a=s.convert(q.tile,q.documentToProof);if(!a)return a.error();return s.convert(a.value(),q.proofToDisplay);}
}